using AppCondominio.SharedKernel;
namespace AppCondominio.Modules.Reservations.Domain;
public enum ReservationStatus{Pending=0,Confirmed=1,Cancelled=2,Completed=3}
public sealed class ReservableArea:AggregateRoot{private ReservableArea(Guid id,Guid communityId,string code,string name,int capacity,decimal fee):base(id){CommunityId=communityId;Code=Req(code);Name=Req(name);Capacity=capacity;Fee=decimal.Round(fee,2);}public Guid CommunityId{get;private set;}public string Code{get;private set;}public string Name{get;private set;}public int Capacity{get;private set;}public decimal Fee{get;private set;}public bool IsActive{get;private set;}=true;public static ReservableArea Create(Guid communityId,string code,string name,int capacity,decimal fee){if(communityId==Guid.Empty||capacity<=0||fee<0)throw new ArgumentException("Invalid reservable area.");return new(Guid.NewGuid(),communityId,code,name,capacity,fee);}public void Disable()=>IsActive=false;static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
public sealed class Reservation:AggregateRoot{private Reservation(Guid id,Guid communityId,Guid areaId,Guid requesterId,DateTimeOffset startsAt,DateTimeOffset endsAt,int guests,decimal fee):base(id){CommunityId=communityId;AreaId=areaId;RequesterId=requesterId;StartsAt=startsAt;EndsAt=endsAt;Guests=guests;Fee=fee;RequestedAtUtc=DateTimeOffset.UtcNow;}public Guid CommunityId{get;private set;}public Guid AreaId{get;private set;}public Guid RequesterId{get;private set;}public DateTimeOffset StartsAt{get;private set;}public DateTimeOffset EndsAt{get;private set;}public int Guests{get;private set;}public decimal Fee{get;private set;}public DateTimeOffset RequestedAtUtc{get;private set;}public ReservationStatus Status{get;private set;}public string? DecisionBy{get;private set;}public static Reservation Create(Guid communityId,Guid areaId,Guid requesterId,DateTimeOffset startsAt,DateTimeOffset endsAt,int guests,decimal fee){if(new[]{communityId,areaId,requesterId}.Any(x=>x==Guid.Empty)||endsAt<=startsAt||guests<=0)throw new ArgumentException("Invalid reservation.");return new(Guid.NewGuid(),communityId,areaId,requesterId,startsAt,endsAt,guests,decimal.Round(fee,2));}public void Confirm(string by){if(Status!=ReservationStatus.Pending)throw new InvalidOperationException("Only pending reservation can be confirmed.");DecisionBy=Req(by);Status=ReservationStatus.Confirmed;}public void Cancel(string by){if(Status is ReservationStatus.Cancelled or ReservationStatus.Completed)throw new InvalidOperationException("Reservation cannot be cancelled.");DecisionBy=Req(by);Status=ReservationStatus.Cancelled;}public void Complete(){if(Status!=ReservationStatus.Confirmed)throw new InvalidOperationException("Only confirmed reservation can complete.");Status=ReservationStatus.Completed;}static string Req(string x)=>string.IsNullOrWhiteSpace(x)?throw new ArgumentException("Required value missing."):x.Trim();}
